//! The entry point table: one slot per EGL and OpenGL ES function that
//! ANGLE exports, and on x64 one thunk per slot from the guest convention
//! (System V) to ANGLE's (Microsoft x64).
//!
//! `src/entries.rs` is generated by `tools/gen_gles.py` from ANGLE's export
//! lists and the Khronos prototypes. [`crate::angle::load`] fills the slots
//! with `GetProcAddress`; [`crate::resolve`] hands guest code the thunk of a
//! filled slot (x64) or ANGLE's own address (arm64, where the guest
//! convention, AAPCS64, is Windows ARM64's for these functions: no
//! variadic functions, x18 is left alone by guest code).
//!
//! A thunk is a plain call through the slot: it contains no Rust code that
//! can panic, and ANGLE reports errors through `glGetError`/`eglGetError`,
//! never by unwinding, so nothing unwinds across the boundary.

use std::sync::atomic::{AtomicUsize, Ordering};

/// The DLL an entry point comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Lib {
    /// `libEGL.dll`.
    Egl,
    /// `libGLESv2.dll` (OpenGL ES 1.x, 2.0 to 3.2 and extensions).
    Gles,
}

/// One entry point.
#[derive(Clone, Copy, Debug)]
pub struct Entry {
    pub name: &'static str,
    pub lib: Lib,
    pub slot: usize,
    /// The x64 thunk (guest convention); 0 on arm64.
    pub thunk: usize,
}

macro_rules! entries {
    ($($i:literal $lib:ident $name:ident($($a:ident: $t:ty),*) $(-> $r:ty)?;)*) => {
        /// Number of entry points.
        pub const COUNT: usize = [$($i),*].len();

        /// ANGLE's address of each entry point (0: not exported).
        pub static SLOTS: [AtomicUsize; COUNT] = [const { AtomicUsize::new(0) }; COUNT];

        /// Every entry point, in slot order.
        pub fn entries() -> Vec<Entry> {
            vec![$(Entry {
                name: stringify!($name),
                lib: Lib::$lib,
                slot: $i,
                #[cfg(target_arch = "x86_64")]
                thunk: x64::$name as usize,
                #[cfg(not(target_arch = "x86_64"))]
                thunk: 0,
            }),*]
        }

        #[cfg(target_arch = "x86_64")]
        #[allow(non_snake_case, clippy::too_many_arguments)]
        mod x64 {
            use super::*;
            $(
                pub unsafe extern "sysv64" fn $name($($a: $t),*) $(-> $r)? {
                    let p = SLOTS[$i].load(Ordering::Relaxed);
                    // SAFETY: `resolve` hands out this thunk only when the
                    // slot holds ANGLE's export of this name, whose C
                    // prototype is this signature (generated from the
                    // Khronos header); ANGLE uses the Microsoft x64
                    // convention (`extern "C"` on this target).
                    unsafe {
                        let f: unsafe extern "C" fn($($t),*) $(-> $r)? = core::mem::transmute(p);
                        f($($a),*)
                    }
                }
            )*
        }
    };
}

include!("entries.rs");

/// ANGLE's address of an entry point by name (0 when absent).
pub fn angle_address(name: &str) -> usize {
    crate::index()
        .get(name)
        .map_or(0, |e| SLOTS[e.slot].load(Ordering::Relaxed))
}
